--- 初始化放置宝箱的锚点物体
---@param num integer 需要宝箱锚点的数量
function BattleEndTreasures:InitAnchorGO(num)
    local needInstantiateNum = num - 1
    if needInstantiateNum <= 0 then return end
    for i = 1, needInstantiateNum, 1 do
        local go = KTool.Instantiate(self.RT_3DItemAnchorRoot.gameObject, self.RT_3DItemAnchor.gameObject)
        -- go.name = "Item3DChest" .. tostring(i + 1)
    end
end

--- 播放宝箱动画
---@param num table 宝箱信息 {{ "quality": 1, "num": 1 }, { "quality": 2, "num": 1 }, { "quality": 3, "num": 1 }}
function BattleEndTreasures:PlayTreasureAnimation(treasureInfo)
    if isNull(treasureInfo) then return end

    -- 初始化宝箱的锚点
    self:InitAnchorGO(#treasureInfo)
    -- 实例化宝箱，并计算位置
    self.treasureGroup = {}
    for i, v in ipairs(treasureInfo) do
        local treasure = treasureInfo[i]
        local anchor = self.RT_3DItemAnchorRoot:GetChild(i - 1)
        local treasureGO = UIBattlingTools.SyncLoadGameObjectByResourceModule(TreasurePrefabPath[treasure.quality], anchor.transform)
        if not isNull(treasureGO) then
            table.insert(self.treasureGroup, {GO = treasureGO, ui = anchor})
            treasureGO.transform.localPosition = Vector3.New(-30, -50, 0)
            treasureGO.transform.localRotation = Quaternion.Euler(0, 180, 0)
            treasureGO.transform.localScale = Vector3.one * 100
            self:DFSSetChildLayer(treasureGO.transform, LayerMask.NameToLayer("UI"))
            -- 设置宝箱的数量
            if treasure.num > 0 then
                local textTF = anchor:GetChild(0)
                KTool.SetActive(textTF.gameObject, true)
                local numText = textTF:GetComponent(typeof(TextMeshProUGUI))
                numText.text = treasure.num
            end
        end
    end
    
    -- 延迟关闭宝箱节点
    self.coDestroyTreasure = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.65))
        GameObject.Destroy(self.controller.gameObject)
        self.coDestroyTreasure = nil
    end)
end

function BattleEndTreasures:DFSSetChildLayer(parent, layer)
    parent.gameObject.layer = layer
    -- print(string.format("name:%s  child:%d", parent.gameObject.name, parent.childCount))
    -- if parent.childCount <= 0 then return end
    for i = 0, parent.childCount - 1, 1 do
        local tf = parent:GetChild(i)
        self:DFSSetChildLayer(tf, layer)
    end
end

function BattleEndTreasures:DestroyTreasures()
    if isNull(self.treasureGroup) then return end

    for i, v in ipairs(self.treasureGroup) do
        GameObject.Destroy(self.treasureGroup[i].GO)
    end
end
